import{_ as a,o as i,c as e,a2 as l}from"./chunks/framework.CBWbbCW8.js";const p=JSON.parse('{"title":"订阅套餐选择","description":"","frontmatter":{},"headers":[],"relativePath":"account/subscriptions.md","filePath":"account/subscriptions.md","lastUpdated":1784973959000}'),o={name:"account/subscriptions.md"};function r(d,t,s,c,n,h){return i(),e("div",null,[...t[0]||(t[0]=[l('<h1 id="订阅套餐选择" tabindex="-1">订阅套餐选择 <a class="header-anchor" href="#订阅套餐选择" aria-label="Permalink to &quot;订阅套餐选择&quot;">​</a></h1><p>订阅套餐用于获得一段时间内的权益或额度。公开前端文案中出现了“我的订阅”“选择订阅套餐”“每月 token”“余额购买订阅”“余额购买订阅优惠码”等能力。</p><h2 id="购买流程" tabindex="-1">购买流程 <a class="header-anchor" href="#购买流程" aria-label="Permalink to &quot;购买流程&quot;">​</a></h2><ol><li>登录 DouDi.ai。</li><li>进入 <code>My Subscriptions</code> 或订阅相关入口。</li><li>查看可购买套餐。</li><li>对比套餐价格、有效期、每月 token、权益和限制。</li><li>选择适合自己的套餐。</li><li>使用余额或可用支付方式完成购买。</li><li>购买后回到 <code>My Subscriptions</code> 查看订阅是否生效。</li></ol><h2 id="如何选择套餐" tabindex="-1">如何选择套餐 <a class="header-anchor" href="#如何选择套餐" aria-label="Permalink to &quot;如何选择套餐&quot;">​</a></h2><table tabindex="0"><thead><tr><th>使用场景</th><th>选择建议</th></tr></thead><tbody><tr><td>只是测试 API</td><td>先小额充值，不急着购买高阶订阅。</td></tr><tr><td>偶尔使用聊天或轻量代码任务</td><td>选择低门槛套餐，关注每月 token 和可用模型。</td></tr><tr><td>经常用 Cursor、Codex CLI、Claude Code</td><td>优先关注高频代码任务的额度、模型权限和稳定性。</td></tr><tr><td>团队或生产项目</td><td>关注额度上限、可用模型、调用日志、发票和续费方式。</td></tr><tr><td>不确定用量</td><td>先用钱包余额跑几天，依据 <code>Usage Logs</code> 再选择套餐。</td></tr></tbody></table><h2 id="购买前需要核对" tabindex="-1">购买前需要核对 <a class="header-anchor" href="#购买前需要核对" aria-label="Permalink to &quot;购买前需要核对&quot;">​</a></h2><ul><li>套餐是否支持你需要的模型。</li><li>套餐是否有每月 token 或额度限制。</li><li>套餐是否有有效期和自动重置规则。</li><li>是否支持优惠码。</li><li>是否能使用余额购买。</li><li>购买后是否支持退款或变更。</li><li>发票选项是否符合你的报销要求。</li></ul><h2 id="余额购买订阅" tabindex="-1">余额购买订阅 <a class="header-anchor" href="#余额购买订阅" aria-label="Permalink to &quot;余额购买订阅&quot;">​</a></h2><p>公开前端文案显示，站点支持“余额购买订阅”。如果该功能对你的账号开放，推荐流程是：</p><ol><li>先在 <code>Wallet</code> 充值余额。</li><li>到订阅页面选择套餐。</li><li>在支付确认页选择余额支付。</li><li>如有优惠码，确认优惠码是否适用于余额购买订阅。</li><li>完成购买后查看余额扣减和订阅状态。</li></ol><h2 id="订阅记录" tabindex="-1">订阅记录 <a class="header-anchor" href="#订阅记录" aria-label="Permalink to &quot;订阅记录&quot;">​</a></h2><p>购买后可以在“我的订阅”中查看订阅记录。如果页面显示“暂无订阅记录”或“暂无订阅套餐”，说明当前账号暂无记录，或平台暂未开放可购买套餐。</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>具体套餐名称、价格、可用模型和每月 token 以登录后页面实时显示为准。公开页面无法直接读取当前可售套餐列表。</p></div>',14)])])}const b=a(o,[["render",r]]);export{p as __pageData,b as default};
